'use strict';
const $=s=>document.querySelector(s), main=$('#main'); let state={view:'overview',symbol:'SPY',overview:null,asset:null,result:null,token:0};
const names={overview:'Market Overview',explorer:'Asset Explorer',lab:'Strategy Lab',worlds:'New Worlds',news:'News & Context',sources:'Sources & Methods',politics:'Politics & Markets',global:'Global Markets',replay:'Storm Replay'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>n==null||!Number.isFinite(n)?'N/A':n.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const pct=n=>n==null?'N/A':`${n>=0?'+':''}${fmt(n*100)}%`;const cls=n=>n==null?'muted':n>=0?'green':'red';
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
async function api(path){const r=await fetch(path);const d=await r.json();if(!r.ok||d.error)throw Error(d.error||'Data retrieval failed');return d;}
const intro=(tag,title,sub)=>`<div class="intro"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${sub}</p></div><span class="pill"><span class="dot"></span>Traceable sources · Daily</span></div>`;
const card=(name,value,note,color='')=>`<div class="card"><small>${name}</small><div class="value ${color}">${value}</div><small>${note}</small></div>`;
const empty=s=>`<div class="empty">${esc(s)}</div>`;
function chart(rows,series,{height=270,percent=false}={}){if(!rows?.length)return empty('No data available');const w=850,h=height,pad=45;const values=rows.flatMap(r=>series.map(s=>r[s.key])).filter(Number.isFinite);if(!values.length)return empty('Insufficient data');let lo=Math.min(...values),hi=Math.max(...values);const diff=hi-lo||1;lo-=diff*.08;hi+=diff*.08;const x=i=>pad+i/Math.max(rows.length-1,1)*(w-pad-15), y=v=>h-pad-(v-lo)/(hi-lo)*(h-pad-12);let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Historical time series"><title>Historical series. Hover over a curve to inspect the date and values.</title>`;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;svg+=`<line x1="${pad}" x2="${w-15}" y1="${y(v)}" y2="${y(v)}" stroke="#24303d"/><text x="2" y="${y(v)+4}">${percent?fmt(v*100,0)+'%':fmt(v,0)}</text>`;}for(const s of series){let segments=[],seg=[];rows.forEach((r,i)=>{if(Number.isFinite(r[s.key]))seg.push(`${x(i)},${y(r[s.key])}`);else if(seg.length){segments.push(seg);seg=[];}});if(seg.length)segments.push(seg);for(const points of segments)svg+=`<polyline points="${points.join(' ')}" class="chartline" stroke="${s.color}"/>`;}const step=Math.max(1,Math.ceil(rows.length/90));rows.forEach((r,i)=>{if(i%step)return;const v=r[series[0].key];if(!Number.isFinite(v))return;svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="6" fill="transparent"><title>${esc(r.date)} ${series.map(s=>esc(s.label)+': '+fmt(r[s.key],3)).join(' / ')}</title></circle>`;});[0,Math.floor(rows.length/2),rows.length-1].forEach(i=>svg+=`<text x="${x(i)}" y="${h-10}" text-anchor="${i===0?'start':i===rows.length-1?'end':'middle'}">${esc(rows[i].date)}</text>`);return svg+'</svg>'+`<div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.label)}</span>`).join('')}</div>`;}
function spark(values,color){if(!values?.length)return '—';const lo=Math.min(...values),range=Math.max(...values)-lo||1;return `<svg class="spark" viewBox="0 0 95 30" aria-label="40-session price history"><polyline fill="none" stroke="${color}" stroke-width="1.5" points="${values.map((v,i)=>`${i/(values.length-1)*95},${28-(v-lo)/range*25}`).join(' ')}"/></svg>`;}
function assetTable(assets){return `<div class="scroll"><table><thead><tr><th>Asset / Name</th><th>Adjusted close</th><th>Day change</th><th>40 sessions</th><th>Observed</th></tr></thead><tbody>${assets.map(a=>`<tr class="clickrow" data-symbol="${esc(a.symbol)}"><td class="symbol">${esc(a.symbol)}<small>${esc(a.name)}</small></td><td>${a.last==null?'N/A':fmt(a.last)}</td><td class="${cls(a.change)}">${pct(a.change)}</td><td>${spark(a.spark,a.change>=0?'#66dfb3':'#fc8a96')}</td><td class="muted">${esc(a.date||'Source unavailable')}${a.stale?' ⚠':''}</td></tr>`).join('')}</tbody></table></div>`;}
function mlast(id){const d=state.overview?.macro?.[id];const row=d?.rows?.at(-1);return row?{...row,data:d,stale:(Date.now()-Date.parse(row.date))/86400000>5||d.cache_status==='stale'}:null;}
function overview(){const d=state.overview;if(!d)return;const assets=d.assets,spy=assets.find(a=>a.symbol==='SPY'),valid=assets.filter(a=>a.last!=null&&!a.stale);const vx=d.vix?.rows?.at(-1),vp=d.vix?.rows?.at(-2),vstale=!vx||(Date.now()-Date.parse(vx.date))/86400000>5||d.vix?.cache_status==='stale';const rate=mlast('DFF'),ten=mlast('DGS10'),two=mlast('DGS2');let spread=null;if(ten&&two){const lookup=new Map(two.data.rows.map(r=>[r.date,r.value]));const common=ten.data.rows.filter(r=>lookup.has(r.date)).at(-1);if(common)spread={date:common.date,value:common.value-lookup.get(common.date)};}const weather=!spy?.last||spy.stale?'Insufficient data':(spy.volatility>.25||(!vstale&&vx?.close>=30))?'Storm watch':spy.last<spy.sma60?'Cloudy · Headwinds':'Partly sunny';const weatherDesc=!spy?.last?'No valid prices. No current signal is generated.':`SPY ${spy.last>=spy.sma60?'above':'below'} 60-session average; 20-session annualized volatility ${pct(spy.volatility)}. Rule-based state indicator, not a price forecast.`;
main.innerHTML=intro('THE MARKET, MADE READABLE','What is the market weather today?','Prices, rates and risk in one view. Find the next question worth researching.')+`<div class="replayTeaser"><div><span class="eyebrow">NEW / MARKET MULTIVERSE</span><h2>Your portfolio. A different history.</h2><p>Navigate a real historical storm and meet the other paths you could have taken.</p></div><button class="primary" data-go="replay">Enter Storm Replay →</button></div><div class="grid4">${card('S&P 500 · SPY',fmt(spy?.last),`${pct(spy?.change)} · ${esc(spy?.date||'Awaiting source')}`,cls(spy?.change))}${card('Effective federal funds rate',rate?fmt(rate.value)+'%':'N/A',rate?`FRED DFF · ${esc(rate.date)}`:'FRED source unavailable')}${card('10Y − 2Y Treasury spread',spread?fmt(spread.value)+' pp':'N/A',spread?`Common observation ${esc(spread.date)}`:'Requires matching observation dates',spread?cls(spread.value):'')}${card('VIX · Cboe volatility index',vx?fmt(vx.close):'N/A',vx?`${esc(vx.date)} · ${vstale?'STALE':'Daily close'} · ${vp?fmt(vx.close-vp.close)+' pts':''}`:'Official Cboe source unavailable',vx&&vx.close>=30?'red':vx&&vx.close>=20?'yellow':'green')}</div>${rate?.data.ingestion?`<div class="notice">Rates: verified FRED official-page snapshot (observed  ${esc(rate.date)}); not an automatic live feed. ${rate.stale?'⚠ Stale: unavailable for current assessment. ':''}<button class="linkbtn" data-go="sources">View evidence →</button></div>`:''}<div class="grid2"><section class="panel weather"><div class="weatherIcon">${weather==='Storm watch'?'☂':weather==='Insufficient data'?'◌':weather==='Cloudy · Headwinds'?'☁':'☀'}</div><div class="eyebrow">MARKET WEATHER / MARKET STATE</div><h2>${weather}</h2><p>${weatherDesc}</p><span class="pill">${spy?.stale?'Stale data · No Trade':'Research signal, not an order'}</span><div class="statrow"><div><small>Available assets</small><b>${valid.length} / ${assets.length}</b></div><div><small>10-year Treasury</small><b>${ten?fmt(ten.value)+'%':'N/A'}</b></div><div><small>Signal frequency</small><b>Daily close</b></div></div></section><section class="panel"><div class="panelHead"><h2>Watchlist</h2><button class="linkbtn" data-go="explorer">Explore assets ↗</button></div>${assetTable(assets.filter(a=>['QQQ','GLD','USO'].includes(a.symbol)))}</section></div><div class="grid2"><section class="panel"><div class="panelHead"><div><h2>Sector temperature</h2><small>21-session return · Select a sector to explore</small></div><span class="pill">ETF PROXY</span></div><div class="heatmap">${assets.filter(a=>a.category==='Sector').map(a=>{const r=a.month_return;return `<button class="heat" data-symbol="${a.symbol}" style="background:${r==null?'#1c2632':r>=0?`rgba(40,129,98,${Math.min(.8,.2+Math.abs(r)*4)})`:`rgba(159,64,80,${Math.min(.8,.2+Math.abs(r)*4)})`}"><small>${esc(a.name)}</small><b>${a.symbol}</b><span>${pct(r)}</span></button>`;}).join('')}</div></section><section class="panel"><div class="panelHead"><h2>Three questions before a trade</h2><span class="pill">EVIDENCE FIRST</span></div><article><h3>01 / Is there historical support?</h3><p>Check performance after costs, against the benchmark and drawdown.</p><button class="linkbtn" data-go="lab">Open Strategy Lab →</button></article><article><h3>02 / What happens when rates change?</h3><p>Explore a parallel yield shock, duration and position risk.</p><button class="linkbtn" data-go="worlds">Explore New Worlds →</button></article><article><h3>03 / Are the data fresh and traceable?</h3><p>Each price retains its date, retrieval time and source. Missing data means waiting.</p><button class="linkbtn" data-go="sources">Inspect the evidence →</button></article></section></div>`+`<section class="panel" style="margin-top:20px"><div class="panelHead"><div><h2>VIX / The market stress lens</h2><small>Official Cboe daily close · Index points · Not directly investable</small></div><button class="linkbtn" data-go="politics">Compare election windows →</button></div>${chart((d.vix?.rows||[]).slice(-252),[{key:'close',label:'VIX daily close',color:'#edc77b'}])}<p class="muted">Heuristic bands: below 20 / calmer; 20–30 / elevated; 30+ / high stress. These thresholds are educational rules, not Cboe recommendations or validated trading strategies. ${link('https://www.cboe.com/tradable-products/vix/vix-historical-data','Cboe source')} · Observed ${esc(vx?.date||'N/A')}. ${vstale?'Stale or missing VIX: no current risk classification.':''}</p></section>`+(valid.length<assets.length?`<div class="notice">${assets.length-valid.length}  assets lack usable, fresh data. Their current signals are unavailable. Inspect Sources & Methods.</div>`:'');}
function selectors(){return `<label>Stock / ETF ticker<input id="symbol" value="${esc(state.symbol)}" maxlength="12" placeholder="e.g. AAPL"></label>`;}
async function explorer(){main.innerHTML=intro('ASSET EXPLORER','Every signal needs evidence.','Explore US stocks and ETFs through trend, momentum and volatility.')+`<div class="controls">${selectors()}<button id="loadAsset" class="primary">Explore asset →</button><label>Chart window<select id="range"><option value="252">Past year</option><option value="126">Past 6 months</option><option value="0">Full history</option></select></label></div><div id="assetBody" class="loading">Loading price history…</div>`;$('#loadAsset').onclick=()=>{state.symbol=$('#symbol').value.trim().toUpperCase();explorer();};$('#symbol').onkeydown=e=>{if(e.key==='Enter')$('#loadAsset').click();};const token=++state.token;try{const a=await api('/api/asset?symbol='+encodeURIComponent(state.symbol));if(token!==state.token||state.view!=='explorer')return;state.asset=a;drawAsset();$('#range').onchange=drawAsset;}catch(e){if(state.view==='explorer')$('#assetBody').innerHTML=`<div class="error">Data unavailable: ${esc(e.message)}. No Trade / Insufficient evidence.</div>`;}}
function drawAsset(){const a=state.asset,s=a.summary;const n=Number($('#range').value);const rows=n?a.rows.slice(-n):a.rows;$('#assetBody').className='';$('#assetBody').innerHTML=`<div class="grid4">${card(esc(a.symbol)+' · '+esc(a.name),fmt(s.last),esc(s.date)+' · '+esc(a.currency))}${card('Day change',pct(s.change),'Consecutive valid sessions',cls(s.change))}${card('RSI · Wilder 14',fmt(s.rsi),'Traditional thresholds: below 30 / above 70')}${card('Annualized volatility',pct(s.volatility),'20-session historical sample')}</div><section class="panel" style="margin-top:20px"><div class="panelHead"><h2>${esc(a.symbol)} / Adjusted price and moving averages</h2><span class="pill">${esc(a.adjustment)}</span></div>${chart(rows,[{key:'close',label:'Adjusted close',color:'#66dfb3'},{key:'sma20',label:'SMA 20',color:'#8daffb'},{key:'sma60',label:'SMA 60',color:'#edc77b'}])}</section><div class="evidence"><section class="panel"><h3>SIGNAL / ${a.symbol.startsWith('^')?'Indicator only':s.stale?'No Trade':s.sma20>s.sma60?'Trend positive':'Wait for trend'}</h3><p>20-session average ${fmt(s.sma20)}; 60-session average ${fmt(s.sma60)}. This is the moving-average rule target. Review its matching historical backtest.</p><button data-go="lab" class="linkbtn">Inspect the backtest →</button></section><section class="panel"><h3>Counterevidence & risk</h3><p>Moving-average rules can whipsaw in sideways markets. RSI ${fmt(s.rsi)}; 63-session momentum ${pct(s.momentum)}; One indicator cannot predict future prices.</p></section><section class="panel"><h3>Data evidence</h3><p>${link(a.url,a.provider)}<br>Observed: ${esc(s.date)}<br>Retrieved: ${esc(a.retrieved_at)}<br>${esc(a.caveat)}</p></section></div>${a.symbol.startsWith('^')?'<div class="notice">This is a risk/yield indicator, not an investable asset. No executable strategy return is inferred.</div>':''}${s.stale?'<div class="error">Prices are stale or refresh failed. Historical inspection only; no actionable current signal.</div>':''}`;}
function lab(){main.innerHTML=intro('STRATEGY LAB','Put your strategy to the test.','Fixed rules. Delayed execution. Real costs. Understand the drawdown before the return.')+`<section class="panel"><div class="controls">${selectors()}<label>Model<select id="strategy"><option value="trend">Trend · SMA 20 / 60</option><option value="momentum">Momentum · 63 sessions</option><option value="reversion">RSI reversion · 30 / 55</option><option value="volatility">Volatility target · 12%</option><option value="rate_guard">Rate-aware risk budget</option></select></label><label>Evaluation period<select id="period"><option value="test">Reserved test · 2024 onward</option><option value="validation">Validation · 2023</option><option value="development">Development · pre-2023</option><option value="all">All history · Exploratory</option></select></label><label>One-way fee (bps)<input id="fee" type="number" value="5" min="0" max="100"></label><label>One-way slippage (bps)<input id="slippage" type="number" value="5" min="0" max="100"></label><button id="run" class="primary">Run backtest ↗</button></div><small>1 bps = 0.01%. Signal at t close. Execute at t+1 close. First holding return at t+2.</small></section><div id="result"><div class="empty">Choose a model and run it. Every displayed result is calculated from historical source data.</div></div>`;$('#run').onclick=runBacktest;}
async function runBacktest(){state.symbol=$('#symbol').value.trim().toUpperCase();const params=new URLSearchParams({symbol:state.symbol,strategy:$('#strategy').value,period:$('#period').value,fee:$('#fee').value,slippage:$('#slippage').value});$('#run').disabled=true;$('#result').innerHTML='<div class="loading"><span class="loader"></span>Calculating from source data. Missing observations are never replaced with synthetic prices.</div>';const token=++state.token;try{const d=await api('/api/backtest?'+params);if(state.view!=='lab'||token!==state.token)return;state.result=d;const m=d.metrics;$('#result').innerHTML=`${d.rate_source?`<div class="notice">Rate-aware model: ${link(d.rate_source.url,"^IRX 13-week Treasury-bill yield proxy")} uses the previous available observation. Higher short yields reduce risk exposure. Fixed educational rule, not optimized. Export includes sources and daily alignment.</div>`:""}<div class="notice">${esc(d.start)} → ${esc(d.end)} · ${d.observations} sessions · Same-period buy-and-hold benchmark · ${d.source.cache_status==='stale'?'Stale cache; historical research only':'Current-vintage provider history'}. A reserved test is not forward live validation.</div><div class="metricGrid">${card('Cumulative return',pct(m.total_return),'Benchmark '+pct(d.benchmark.total_return),cls(m.total_return))}${card('CAGR',pct(m.cagr),'Requires 252+ sessions')}${card('Sharpe',fmt(m.sharpe),'Risk-free reference 0 · 60+ sessions')}${card('Maximum drawdown',pct(m.max_drawdown),'Includes starting wealth of 1.0','red')}${card('Annualized arithmetic return',pct(m.annual_return),'Mean daily return × 252')}${card('Annualized volatility',pct(m.volatility),'Daily sample stdev × √252')}${card('Sortino',fmt(m.sortino),'Downside RMS · MAR 0')}${card('Trade win rate',pct(m.win_rate),`${m.trade_count} closed trades`)}</div><section class="panel"><div class="panelHead"><h2>Equity curve · Initial wealth 1</h2><button id="export" class="btn">Export full result ↓</button></div>${chart(d.curve,[{key:'strategy',label:'Strategy, net of costs',color:'#66dfb3'},{key:'benchmark',label:'Buy & hold, net of costs',color:'#8daffb'}])}</section><div class="grid2 equal"><section class="panel"><h2>Strategy drawdown</h2>${chart(d.curve,[{key:'drawdown',label:'Drawdown',color:'#fc8a96'}],{height:210,percent:true})}</section><section class="panel"><h2>EVIDENCE / ${m.total_return>0?'Positive historical return':'No historical profit in this window'}</h2><p class="muted">Latest historical model target ${pct(d.latest_target)}; This is a fixed-rule research output, not personalized advice. Volatility and rate-aware models rebalance daily.</p><p class="muted">Total turnover ${fmt(d.turnover)} ×. Sum of daily cost fractions: ${pct(d.cost_drag_sum)} (not a compounded performance difference). Idle cash earns zero.</p><p class="muted">If the strategy underperforms, drawdown exceeds your tolerance, or data is stale, consider waiting / No Trade.</p></section></div><section class="panel" style="margin-top:20px"><h2>Trade log</h2><div class="scroll"><table><thead><tr><th>Entry</th><th>Exit</th><th>Adjusted entry price</th><th>Adjusted exit price</th><th>Return after costs</th></tr></thead><tbody>${d.trades.slice(-100).map(t=>`<tr><td>${esc(t.entry_date)}</td><td>${esc(t.exit_date)}${t.forced_exit?' *':''}</td><td>${fmt(t.entry_price)}</td><td>${fmt(t.exit_price)}</td><td class="${cls(t.net_return)}">${pct(t.net_return)}</td></tr>`).join('')}</tbody></table></div><small>${d.fills?.length||0} execution fills (including all rebalances) are retained in the JSON export. Latest 100 closed position episodes shown below; export the full log. * Terminal liquidation. Fractional-exposure models rebalance; per-trade return and win rate are N/A.</small><details><summary>Assumptions and data sources</summary><ul>${d.assumptions.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><pre>${esc(JSON.stringify({asset_source:d.source,rate_source:d.rate_source},null,2))}</pre></details></section>`;$('#export').onclick=()=>downloadJSON(d,`alphascope-${d.symbol}-${d.strategy}.json`);}catch(e){if(state.view==='lab')$('#result').innerHTML=`<div class="error">No valid backtest: ${esc(e.message)}</div>`;}finally{if($('#run'))$('#run').disabled=false;}}
function worlds(){main.innerHTML=intro('NEW WORLDS / INTERACTIVE SCENARIOS','What if rates enter a different world?','Move the scenario controls to explore a rate shock. These are educational models, not market forecasts.')+`<div class="notice">HYPOTHETICAL SCENARIO · Not a market observation or a backtested strategy. Duration and risk budgets are user assumptions, not product facts.</div><div class="grid2 equal"><section class="panel"><h2>01 / Change the conditions</h2><p class="muted">Observed DFF: ${mlast('DFF')?fmt(mlast('DFF').value)+'% ('+esc(mlast('DFF').date)+')':'Source unavailable'}. Policy rates and individual yields need not move together.</p><label>Assumed parallel yield shift <strong id="shockLabel"></strong><input id="shock" type="range" min="-200" max="200" step="25" value="50"></label><div class="controls"><label>Assumed modified duration (years)<input id="duration" type="number" min="0" max="30" step="0.5" value="7"></label><label>Daily loss budget (USD)<input id="budget" type="number" min="0" value="100" style="width:150px"></label><label>Assumed annual volatility %<input id="sigma" type="number" min="1" max="200" value="20"></label></div><small>Model: ΔP/P ≈ −D × Δy. Ignores convexity, credit spreads and coupons. This is not a GLD or USO valuation formula.</small></section><section class="panel weather"><div class="eyebrow">DURATION LENS</div><h2>Hypothetical bond sensitivity</h2><div id="impact" class="big"></div><p id="scenarioText"></p><div class="bar"><div id="impactBar"></div></div></section></div><div class="grid2 equal"><section class="panel"><h2>02 / Translate a risk budget into position size</h2><div class="big" id="position"></div><p class="muted">Model position size (USD) = daily loss budget / (1.645 × annual volatility / √252). Assumes independent, normally distributed returns. A 95% one-day VaR can still be exceeded.</p><small>Excludes gaps, fat tails, correlations, leverage and liquidity risk. This is not a guaranteed loss limit.</small></section><section class="panel"><h2>03 / Gold, oil and sector transmission</h2><article><h3>Gold · GLD proxy</h3><p>Watch real yields, the US dollar and safe-haven demand. Effects can offset one another; a rate decision alone cannot determine price direction.</p></article><article><h3>Oil · USO proxy</h3><p>Also study supply, demand, inventories and geopolitics. USO includes roll and expense effects; it is not spot oil or executable futures P&L.</p></article><button class="linkbtn" data-go="lab">Test rules on real history →</button></section></div>`;function update(){const shock=Number($('#shock').value),duration=Number($('#duration').value),sigma=Number($('#sigma').value)/100,budget=Number($('#budget').value);const change=-duration*shock/10000;$('#shockLabel').textContent=`${shock>=0?'+':''}${shock} bps`;$('#impact').textContent=pct(change);$('#impact').className='big '+cls(change);$('#impactBar').style.width=Math.min(100,Math.abs(change)*400)+'%';$('#scenarioText').textContent=`With yields ${shock>=0?'rising':'falling'} ${Math.abs(shock)} bps、modified duration ${duration} years, the first-order price estimate is ${change>=0?'rising':'falling'}. Large shocks increase approximation error.`;$('#position').textContent=sigma>0&&budget>=0?'$'+fmt(budget/(1.645*sigma/Math.sqrt(252)),0):'N/A';}['shock','duration','sigma','budget'].forEach(id=>$('#'+id).oninput=update);update();}
function newsView(){const n=state.overview?.news;main.innerHTML=intro('NEWS & CONTEXT','Read the facts. Then form a view.','Official monetary-policy releases with original titles, dates and source links.')+`<div class="notice">Federal Reserve policy releases are shown below. For political coverage and election windows, open Politics & Markets. No generative factual summaries; news never enters historical strategy signals.</div><section class="panel">${n?.items?.length?n.items.map(i=>`<article><small>${esc(i.source)} · ${esc(i.published)} · ${esc(i.scope)}</small><h3>${link(i.url,i.title)}</h3><p>${esc(i.interpretation)}</p></article>`).join(''):empty('News source unavailable: '+(n?.error||'Check the connection'))}<small>Retrieved: ${esc(n?.retrieved_at||'N/A')} · ${n?.cache_status==='stale'?'Refresh failed; cache may be stale':'RSS may be delayed'}</small></section>`;}
function sources(){const o=state.overview;main.innerHTML=intro('PROVENANCE & METHODS','Every number has a source.','Inspect providers, observation dates, retrieval times, adjustments and model assumptions.')+`<div class="grid2 equal"><section class="panel"><h2>Data policy</h2><p class="muted">Real-source mode. Missing data shows N/A. Prices older than five calendar days, or a failed refresh, are flagged. Only completed sessions are included. Cache refresh: six hours.</p><p>${link('https://ranaroussi.github.io/yfinance/','Yahoo data-use guidance')} · For personal research. Public commercial use requires a separate data-license review.</p><p>${link('https://fred.stlouisfed.org/series/DFF','FRED DFF')} / ${link('https://fred.stlouisfed.org/series/DGS10','DGS10')} / ${link('https://www.federalreserve.gov/feeds/feeds.htm','Federal Reserve RSS')}</p></section><section class="panel"><h2>Backtest methods & limitations</h2><p class="muted">Five fixed-rule models. Long or cash, no leverage. Execute at t+1 close; first holding return at t+2. Both-side fees, slippage and terminal liquidation are included.</p><p class="muted">Fixed calendar split: development before 2023; validation in 2023; reserved test from 2024. Repeated inspection compromises test independence. Current news and current FRED snapshots never enter historical signals.</p><p class="muted">GLD and USO are ETF proxies. Contract specifications, margin and rolling futures are not modeled. There is no executable futures backtest.</p></section></div><section class="panel" style="margin-top:20px"><h2>Price provenance</h2><div class="scroll"><table><thead><tr><th>Instrument</th><th>Provider / Original source</th><th>Observed date</th><th>Retrieved (UTC)</th><th>Status</th></tr></thead><tbody>${(o?.assets||[]).map(a=>`<tr><td>${esc(a.symbol)}</td><td>${a.url?link(a.url,'Yahoo Finance'):'Yahoo Finance(connection failed)'}</td><td>${esc(a.date||'N/A')}</td><td>${esc(a.retrieved_at||'N/A')}</td><td>${a.last==null?'Unavailable':a.stale?'Stale':'Available'}<details><summary>Inspect provenance</summary><pre>${esc(JSON.stringify(a,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><h2>Rate-aware strategy source</h2><details><summary>Yahoo ^IRX · 13-week Treasury-bill yield</summary><pre>${esc(JSON.stringify(o?.rate_proxy,null,2))}</pre></details><h2>VIX and political-news provenance</h2><details><summary>Cboe VIX official daily history</summary><pre>${esc(JSON.stringify({...o?.vix,rows:undefined,last_observation:o?.vix?.rows?.at(-1)},null,2))}</pre></details><details><summary>BBC News US & Canada feed</summary><pre>${esc(JSON.stringify({...o?.political_news,items:undefined},null,2))}</pre></details><h2>Macro observations</h2>${Object.entries(o?.macro||{}).map(([k,v])=>{const row=v.rows?.at(-1);return `<details><summary>${esc(k)} · ${row?fmt(row.value)+'% · '+esc(row.date):'Unavailable'}${v.ingestion?' · Official-page snapshot':''}</summary><p>${link('https://fred.stlouisfed.org/series/'+k,'FRED Original source')}</p><pre>${esc(JSON.stringify({...v,rows:undefined,last_observation:row},null,2))}</pre></details>`;}).join('')}<div class="notice">FRED observations use observation dates, not point-in-time release timestamps, and may be revised. They provide macro context only. The rate-aware backtest uses separately lagged historical ^IRX observations.</div></section>`;}
function downloadJSON(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function navigate(view){state.token++;state.view=view;location.hash=view;$('#crumb').textContent=names[view];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));({overview,explorer,lab,worlds,news:newsView,sources,politics,global:globalMarkets,replay:stormReplay}[view]||overview)();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-view],[data-go],[data-symbol]');if(!b)return;if(b.dataset.symbol){state.symbol=b.dataset.symbol;navigate('explorer');}else navigate(b.dataset.view||b.dataset.go);});
$('#reload').onclick=async()=>{main.innerHTML='<div class="loading">Reloading data and source caches…</div>';await init();};
async function init(){try{state.overview=await api('/api/overview');const v=location.hash.slice(1);navigate(names[v]?v:'overview');}catch(e){main.innerHTML=intro('DATA CONNECTION','Data not ready','No conclusions will be generated from invented observations.')+`<div class="error">${esc(e.message)}</div><button data-go="worlds">Explore rate scenarios</button>`;}}
setInterval(()=>$('#clock').textContent=new Date().toLocaleString('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+' London',1000);init();

function politics(){
  const n=state.overview?.political_news;
  main.innerHTML=intro('POLITICS & MARKETS','When politics moves into the market.','Read sourced headlines, then inspect what stocks, sectors and VIX actually did around US midterms.')+`
  <div class="controls"><label>Election event<select id="event"><option value="2026-midterms">2026 US midterms · 3 November</option><option value="2022-midterms">2022 US midterms · 8 November</option><option value="2018-midterms">2018 US midterms · 6 November</option></select></label><label>Asset / sector<select id="eventSymbol"><option>SPY</option><option>QQQ</option><option>XLK</option><option>XLF</option><option>XLE</option><option>XLV</option><option>XLI</option><option>XLY</option><option>XLP</option><option>XLU</option><option>XLRE</option><option>XLB</option><option>XLC</option><option>GLD</option><option>USO</option></select></label><label>Sessions before / after<select id="eventWindow"><option value="20">20 sessions</option><option value="5">5 sessions</option><option value="60">60 sessions</option></select></label><button id="study" class="primary">Explore event →</button></div>
  <div id="eventResult"><div class="loading"><span class="loader"></span>Calculating the historical event window…</div></div>
  <div class="grid2 equal"><section class="panel"><div class="panelHead"><h2>Political transmission map</h2><span class="pill">HYPOTHESES, NOT NEWS FACTS</span></div><article><h3>Congress → fiscal policy → yields & valuations</h3><p>Tax and spending proposals can affect expected earnings, deficits and discount rates. The response depends on what was already priced in; party labels do not determine returns.</p></article><article><h3>Trade policy → supply chains → sector margins</h3><p>Tariffs and trade restrictions can alter costs and demand. Inspect industrials, technology and consumer sectors, and look for enacted policy rather than headlines alone.</p></article><article><h3>Uncertainty → option pricing → VIX</h3><p>VIX measures expected volatility, not market direction. Falling VIX after an election does not prove political uncertainty was its only driver.</p></article><small>No causal model or profitable election strategy is claimed. News has not been joined to historical trading signals.</small></section>
  <section class="panel"><div class="panelHead"><h2>US & Canada headlines</h2><span class="pill">ORIGINAL RSS TITLES</span></div><p>${link('https://www.bbc.com/news','BBC News')} · ${link(n?.url||'https://feeds.bbci.co.uk/news/world/us_and_canada/rss.xml','Original feed')}</p><small>Politics badges are application keyword annotations. The full available feed is retained; headlines can include nonpolitical stories. Retrieved ${esc(n?.retrieved_at||'N/A')}. ${n?.cache_status==='stale'?'Refresh failed; potentially stale.':''}</small>${n?.items?.length?n.items.map(i=>`<article><small>${esc(i.published)} ${i.political_match?'<span class="pill">POLITICS KEYWORD</span>':''}</small><h3>${link(i.url,i.title)}</h3></article>`).join(''):empty('Political feed unavailable. No invented headlines.')}<p class="muted">Personal, non-commercial RSS reader. Read publisher articles for facts and context; no AI-generated factual summaries.</p></section></div>`;
  $('#study').onclick=loadEventStudy;loadEventStudy();
}
async function loadEventStudy(){
  const event=$('#event').value,symbol=$('#eventSymbol').value,windowSize=$('#eventWindow').value,token=++state.token;
  $('#study').disabled=true;$('#eventResult').innerHTML='<div class="loading"><span class="loader"></span>Inspecting completed historical sessions…</div>';
  try{
    const d=await api('/api/event-study?'+new URLSearchParams({event,symbol,window:windowSize}));
    if(state.view!=='politics'||state.token!==token)return;
    const r=d.summary,base=d.baseline_date;let equityChart=chart(d.curve,[{key:'asset',label:symbol+' vs pre-event close',color:'#66dfb3'},{key:'benchmark',label:'SPY vs pre-event close',color:'#8daffb'}],{percent:true});
    const ix=d.curve.findIndex(r=>r.session===0),markerX=45+ix/Math.max(1,d.curve.length-1)*(850-45-15);
    const marker=`<line x1="${markerX}" x2="${markerX}" y1="25" y2="225" stroke="#edc77b" stroke-dasharray="4 4"/><text x="${Math.min(markerX+6,730)}" y="20">Election day / Session 0</text>`;
    equityChart=equityChart.replace('</svg>',marker+'</svg>');
    $('#eventResult').innerHTML=`<div class="notice">DESCRIPTIVE EVENT STUDY · Not a strategy backtest or causal estimate. Baseline: ${esc(base)} close. Last observation: ${esc(r.end_date)}. ${d.complete?`Full +${d.requested_post_sessions}-session window available.`:`PARTIAL WINDOW: only through session +${d.available_post_sessions} of requested +${d.requested_post_sessions}; future observations remain unavailable.`}</div><div class="grid4">${card(symbol+' event-window return',pct(r.asset_return),'Pre-event close → latest window close',cls(r.asset_return))}${card('SPY benchmark',pct(r.benchmark_return),'Identical baseline and end dates',cls(r.benchmark_return))}${card('Difference vs SPY',pct(r.excess_return),'Descriptive spread, not causal alpha',cls(r.excess_return))}${card('VIX change',r.vix_change_points==null?'N/A':`${r.vix_change_points>=0?'+':''}${fmt(r.vix_change_points)} pts`,'Cboe index points, not investment return',r.vix_change_points>0?'yellow':'green')}</div><section class="panel" style="margin-top:20px"><div class="panelHead"><div><h2>${esc(d.event.name)} / Price response</h2><small>${link(d.event.source,'Election date: FEC calendar')}</small></div><button id="exportEvent" class="btn">Export event study ↓</button></div>${equityChart}<p class="muted">Session -1 is the common pre-election closing baseline. Prices before that baseline can be negative or positive relative to it. Election results and later policy changes may be learned over several days.</p></section><div class="grid2 equal"><section class="panel"><h2>VIX around the election</h2>${chart(d.curve,[{key:'vix',label:'Official Cboe VIX close (points)',color:'#edc77b'}],{height:240})}<small>Levels measure expected 30-day S&P 500 volatility, not expected direction. Missing date matches are shown as gaps.</small></section><section class="panel"><h2>Checkpoints / from ${esc(base)}</h2><div class="scroll"><table><thead><tr><th>Session</th><th>Date</th><th>${esc(symbol)}</th><th>SPY</th><th>Δ VIX pts</th></tr></thead><tbody>${[0,1,5,20,60].filter(k=>k<=Number(windowSize)).map(k=>{const row=d.curve.find(x=>x.session===k);return `<tr><td>+${k}</td><td>${esc(row?.date||'Not available')}</td><td>${row?pct(row.asset):'N/A'}</td><td>${row?pct(row.benchmark):'N/A'}</td><td>${row?fmt(row.vix_change_points):'N/A'}</td></tr>`;}).join('')}</tbody></table></div><details><summary>Method and provenance</summary><p>${esc(d.methodology)}</p><pre>${esc(JSON.stringify(d.sources,null,2))}</pre></details></section></div><section class="panel" style="margin-top:20px"><div class="panelHead"><h2>Sector response / same election window</h2><small>ETF proxies · Descriptive only</small></div><div id="eventSectors" class="loading">Loading sector comparisons…</div></section><div class="evidence"><section class="panel"><h3>What the data show</h3><p>Observed asset and benchmark performance, VIX changes, date alignment and missing future sessions.</p></section><section class="panel"><h3>What this cannot establish</h3><p>Election causality, party-specific alpha, or statistical significance. Three hand-selected events are too few to validate a robust election strategy.</p></section><section class="panel"><h3>Competing explanations</h3><p>Inflation releases, Fed decisions, earnings, geopolitical developments, prior positioning and policy expectations can overlap the election window.</p></section></div>`;
    $('#exportEvent').onclick=()=>downloadJSON(d,`alphascope-${event}-${symbol}.json`);
    const sectors=state.overview.assets.filter(a=>a.category==='Sector');
    const sectorResults=await Promise.all(sectors.map(async a=>{try{return {...a,study:await api('/api/event-study?'+new URLSearchParams({event,symbol:a.symbol,window:windowSize}))};}catch(e){return {...a,error:e.message};}}));
    if(state.view!=='politics'||state.token!==token)return;
    $('#eventSectors').className='scroll';$('#eventSectors').innerHTML=`<table><thead><tr><th>Sector proxy</th><th>Window return</th><th>Difference vs SPY</th><th>Last session</th><th>Coverage</th></tr></thead><tbody>${sectorResults.map(a=>`<tr><td class="symbol">${esc(a.symbol)}<small>${esc(a.name)}</small></td><td class="${cls(a.study?.summary.asset_return)}">${pct(a.study?.summary.asset_return)}</td><td>${pct(a.study?.summary.excess_return)}</td><td>${esc(a.study?.summary.end_date||'N/A')}</td><td>${a.study?(a.study.complete?'Complete':`Partial: +${a.study.available_post_sessions}`):esc(a.error)}</td></tr>`).join('')}</tbody></table>`;
  }catch(e){if(state.view==='politics'&&state.token===token)$('#eventResult').innerHTML=`<div class="error">Event study unavailable: ${esc(e.message)}. No synthetic outcomes are substituted.</div>`;}
  finally{if($('#study')&&state.token===token)$('#study').disabled=false;}
}

async function globalMarkets(){
  main.innerHTML=intro('GLOBAL MARKET OBSERVATORY','Ten markets. One global perspective.','Follow ten representative indices across the US, UK, Japan, China, Hong Kong and other major markets.')+'<div id="globalBody" class="loading"><span class="loader"></span>Loading dated local-market index observations…</div>';
  const token=++state.token;
  try{
    const d=state.world||await api('/api/global-markets');if(state.view!=='global'||state.token!==token)return;state.world=d;
    const colors=['#66dfb3','#8daffb','#edc77b','#fc8a96','#a897ef','#74d0ec','#e6a76a','#a3c87e','#df92bf','#c0d5de'];
    const maxMove=Math.max(.01,...d.markets.map(m=>Math.abs(m.index.change||0)));
    $('#globalBody').className='';$('#globalBody').innerHTML=`<div class="notice">Ten selected major-market indices, not an exchange-size ranking. Each card shows its latest completed local-market session, currency basis and source date. ${d.missing_symbols.length?'Unavailable series: '+esc(d.missing_symbols.join(', '))+'. No synthetic values are substituted.':''}</div>
    <div class="marketGrid">${d.markets.map(m=>{const x=m.index;return `<button class="marketCard panel" data-global-symbol="${esc(m.index_symbol)}" style="text-align:left"><small>${esc(m.region)}</small><h3>${esc(m.index_label)}</h3><div class="marketCap" style="font-size:23px">${fmt(x.last)}</div><small>Index points · ${esc(x.currency||'N/A')} basis</small><div class="marketDivider"></div><div class="${cls(x.change)}">${pct(x.change)} <small>Latest-session change</small></div><div style="margin-top:12px">${spark(x.spark,x.change>=0?'#66dfb3':'#fc8a96')}</div><small>${esc(x.date||'Unavailable')}${x.stale?' · STALE':''}</small><small>${esc(m.index_symbol)}</small></button>`;}).join('')}</div>
    <div class="grid2 equal"><section class="panel"><div class="panelHead"><h2>Latest-session moves</h2><span class="pill">LOCAL-CURRENCY INDEX CHANGE</span></div>${d.markets.map(m=>{const x=m.index;return `<div class="rankBar"><div><span>${esc(m.region)} · ${esc(m.index_label)}</span><b class="${cls(x.change)}">${pct(x.change)}</b></div><div class="bar"><div style="width:${Math.abs(x.change||0)/maxMove*100}%;background:${x.change>=0?'#66dfb3':'#fc8a96'}"></div></div></div>`;}).join('')}<small>Latest available session for each market. Different trading calendars and closing times mean these moves are not necessarily simultaneous.</small></section><section class="panel"><div class="panelHead"><h2>How to read this page</h2><span class="pill">COMPARE WITH CARE</span></div><article><h3>Ten markets, selected for geographic coverage.</h3><p>${esc(d.selection.method)}</p></article><article><h3>Index levels are not comparable market sizes.</h3><p>A higher index level does not imply a larger market. The comparison chart rebases each available series to 100 on a common date.</p></article><article><h3>Local returns are not a USD portfolio.</h3><p>Currency exposure, constituents, index methodology and non-simultaneous closes differ. DAX is commonly quoted as a performance index, while several other indices are price indices.</p></article><button class="linkbtn" data-go="politics">Explore politics, sectors and VIX →</button></section></div>
    <section class="panel" style="margin-top:20px"><div class="panelHead"><div><h2>Global index comparison / rebased to 100</h2><small>Latest 126 common observations · Exact date intersection · Local currency</small></div><button id="exportGlobal" class="btn">Export data & sources ↓</button></div>${chart(d.comparison,d.markets.filter(m=>d.comparison[0]?.[m.index_symbol]!=null).map((m,i)=>({key:m.index_symbol,label:m.index_label,color:colors[i]})),{height:320})}<p class="muted">${esc(d.comparison_method)}</p></section>
    <section class="panel" style="margin-top:20px"><h2>Daily index observations & provenance</h2><div class="scroll"><table><thead><tr><th>Market / index</th><th>Index level</th><th>Day change</th><th>21-session return</th><th>Observed</th><th>Exchange timezone</th><th>Sources</th></tr></thead><tbody>${d.markets.map(m=>{const x=m.index;return `<tr><td class="symbol">${esc(m.region)}<small>${esc(m.index_label)} · ${esc(m.index_symbol)}</small></td><td>${fmt(x.last)}<small> ${esc(x.currency||'')}</small></td><td class="${cls(x.change)}">${pct(x.change)}</td><td class="${cls(x.month_return)}">${pct(x.month_return)}</td><td>${esc(x.date||'N/A')}${x.stale?' ⚠ STALE':''}</td><td>${esc(x.timezone||'N/A')}</td><td>${x.url?link(x.url,'Index provider'):'Unavailable'}<details><summary>Metadata</summary><pre>${esc(JSON.stringify(x,null,2))}</pre></details></td></tr>`;}).join('')}</tbody></table></div><details><summary>Selection methodology</summary><p>${esc(d.selection.method)}</p></details></section>`;
    $('#exportGlobal').onclick=()=>downloadJSON(d,'alphascope-global-markets.json');
  }catch(e){if(state.view==='global'&&state.token===token)$('#globalBody').innerHTML=`<div class="error">Global data unavailable: ${esc(e.message)}. No invented index data are substituted.</div>`;}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-global-symbol]');if(!b?.dataset.globalSymbol)return;state.symbol=b.dataset.globalSymbol;navigate('explorer');});

async function replayPost(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok||data.error)throw Error(data.error||'Replay request failed');return data;}
function replayWeights(prefix,weights){return `<div class="allocationGrid">${['SPY','GLD','USO','TLT'].map((s,i)=>`<label><span>${s} <small>${['US equities','Gold ETF proxy','Oil ETF proxy','Treasury ETF'][i]}</small><b id="${prefix}${s}Value">${fmt((weights[s]||0)*100,0)}%</b></span><input id="${prefix}${s}" type="range" min="0" max="100" step="5" value="${(weights[s]||0)*100}"></label>`).join('')}</div><div class="cashReadout">Unallocated cash <b id="${prefix}Cash"></b><span id="${prefix}Warning" class="red"></span></div>`;}
function collectReplayWeights(prefix){return Object.fromEntries(['SPY','GLD','USO','TLT'].map(s=>[s,Number($('#'+prefix+s).value)/100]));}
function wireReplayWeights(prefix,callback=()=>{}){function update(){const w=collectReplayWeights(prefix),total=Object.values(w).reduce((a,b)=>a+b,0);for(const s of Object.keys(w))$('#'+prefix+s+'Value').textContent=fmt(w[s]*100,0)+'%';$('#'+prefix+'Cash').textContent=fmt((1-total)*100,0)+'%';$('#'+prefix+'Warning').textContent=total>1.0000001?' Total allocation must not exceed 100%.':'';callback(total<=1.0000001);}for(const s of ['SPY','GLD','USO','TLT'])$('#'+prefix+s).oninput=update;update();}
function stormReplay(){if(state.replay){renderStormReplay();return;}renderReplaySetup();}
function renderReplaySetup(){main.innerHTML=intro('MARKET MULTIVERSE / STORM REPLAY','Your capital. Three possible journeys.','Build a portfolio, enter a historical world, and discover what your decisions would have changed.')+`<div class="replayWelcome panel"><div><span class="eyebrow">THE CHALLENGE</span><h2>Can your portfolio weather the storm?</h2><p>Start with a hypothetical $100,000. See only the history revealed so far, then choose your next move. Your route is compared with buy-and-hold and a fixed risk rule, after costs.</p><div class="legend"><span>01 / Build your ship</span><span>02 / Navigate the storm</span><span>03 / Meet your other selves</span></div></div><div class="welcomePlanet" aria-hidden="true">✧</div></div><div class="grid2 equal"><section class="panel"><h2>Choose a historical world</h2><div class="controls"><label>World<select id="replayWorld"><option value="2020-storm">2020 / The volatility storm</option><option value="2022-rates">2022 / The rate-shift world</option></select></label><label>Drawdown budget<select id="replayBudget"><option value=".2">20% of peak wealth</option><option value=".1">10% of peak wealth</option><option value=".3">30% of peak wealth</option></select></label></div><article><h3>History is real. The portfolio is hypothetical.</h3><p>Prices come from source-tagged adjusted ETF histories. VIX is from Cboe. Historical Fed releases are revealed only after publication.</p></article><small>This is a replay of known history, not a blind validation or a prediction contest. The drawdown budget is a visual learning threshold, not a stop-loss or a probability of survival.</small></section><section class="panel"><h2>Build your launch allocation</h2><p class="muted">Cash earns zero. Long-only ETF exposures; no leverage or futures contracts.</p>${replayWeights('launch',{SPY:.6,GLD:.15,USO:.1,TLT:.1})}<button id="launchReplay" class="primary" style="width:100%;margin-top:18px">Launch into history →</button><div id="launchError"></div></section></div>`;wireReplayWeights('launch',valid=>$('#launchReplay').disabled=!valid);$('#launchReplay').onclick=async()=>{const payload={scenario:$('#replayWorld').value,weights:collectReplayWeights('launch'),budget:Number($('#replayBudget').value)};$('#launchReplay').disabled=true;$('#launchReplay').textContent='Preparing source-backed history…';try{state.replay=await replayPost('/api/replay/start',payload);if(state.view==='replay')renderStormReplay();}catch(e){if($('#launchError'))$('#launchError').innerHTML=`<div class="error">${esc(e.message)}</div>`;if($('#launchReplay')){$('#launchReplay').disabled=false;$('#launchReplay').textContent='Launch into history →';}}};}
function shipIllustration(d){const color=d.budget_breached?'#fc8a96':d.budget_used>.6?'#edc77b':'#66dfb3';return `<svg class="shipScene" viewBox="0 0 520 300" role="img" aria-label="Portfolio spacecraft; orbit arcs visualize the historical replay, not financial forecasts"><defs><radialGradient id="planetGlow"><stop offset="0" stop-color="${color}" stop-opacity=".22"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></radialGradient></defs><circle cx="260" cy="145" r="140" fill="url(#planetGlow)"/><ellipse cx="260" cy="150" rx="210" ry="60" fill="none" stroke="#2e4549" transform="rotate(-18 260 150)"/><ellipse cx="260" cy="150" rx="140" ry="105" fill="none" stroke="#2e4549" stroke-dasharray="3 8" transform="rotate(20 260 150)"/><circle cx="260" cy="145" r="86" fill="#101e27" stroke="${color}" stroke-opacity=".5"/><path d="M260 82 L285 137 L278 182 L242 182 L235 137Z" fill="#a5b4c4"/><path d="M260 82 L260 182 L242 182 L235 137Z" fill="#e4edf4"/><circle cx="260" cy="134" r="13" fill="#102a35" stroke="${color}" stroke-width="3"/><path d="M242 158 L222 186 L244 177 M278 158 L298 186 L276 177" fill="${color}"/><path class="shipFlame" d="M248 188 L260 215 L272 188" fill="${color}" opacity=".8"/><circle cx="81" cy="112" r="11" fill="#8daffb"/><circle cx="442" cy="173" r="16" fill="#edc77b"/><circle cx="351" cy="55" r="5" fill="#fc8a96"/>${[[50,45],[140,230],[460,70],[388,258],[188,48],[48,238],[490,243]].map(([x,y])=>`<path d="M${x-3} ${y}h6 M${x} ${y-3}v6" stroke="#8a9aab"/>`).join('')}<text x="55" y="145" fill="#8a9aab" font-size="10" font-family="monospace">COSTS</text><text x="421" y="208" fill="#8a9aab" font-size="10" font-family="monospace">RISK</text><text x="260" y="270" text-anchor="middle" fill="${color}" font-size="11" font-family="monospace">${d.complete?'HISTORICAL ROUTE COMPLETE':'NEXT OBSERVATIONS HIDDEN'}</text></svg>`;}
function renderStormReplay(){
 const d=state.replay,p=d.paths.player,hold=d.paths.hold,rule=d.paths.rule,m=p.metrics;const lost=Math.abs(m.max_drawdown||0),latest=d.curve.at(-1),prev=d.curve.length>1?d.curve.at(-2):latest;
 main.innerHTML=intro('MARKET MULTIVERSE / STORM REPLAY',d.complete?'Meet your other selves.':d.scenario_name,d.complete?'Three routes through the same history. Compare the trade-offs, then inspect the evidence.':'Make a decision with what is visible now. The next chapter is still hidden.')+`<div class="replayStatus"><span class="pill"><span class="dot"></span>OBSERVED CLOSE / ${esc(d.as_of)}</span><span class="pill">ROUND ${d.turn} · ${d.revealed_sessions} SESSIONS REVEALED</span><button id="restartReplay" class="linkbtn">Build a new ship ↗</button><button id="exportReplay" class="btn">Export revealed evidence ↓</button></div><div class="grid2 replayHero"><section class="panel shipPanel">${shipIllustration(d)}<div class="replayProgress"><span>Historical journey</span><b>${fmt(d.progress*100,0)}% revealed</b></div><div class="bar"><div style="width:${d.progress*100}%"></div></div><small>Spaceflight is a visual metaphor. All displayed portfolio changes are calculated from observed historical prices.</small></section><section class="panel"><div class="eyebrow">YOUR PORTFOLIO / HYPOTHETICAL USD</div><div class="big">$${fmt(p.nav,0)}</div><div class="${cls(p.nav/d.initial_capital-1)}">${pct(p.nav/d.initial_capital-1)} since launch</div><div class="statrow"><div><small>Largest drawdown</small><b class="red">${pct(m.max_drawdown)}</b></div><div><small>VIX at this close</small><b>${fmt(d.vix)} pts</b></div><div><small>Execution costs</small><b>$${fmt(p.cost_usd)}</b></div></div><div class="budgetMeter"><div><small>Drawdown budget used</small><b class="${d.budget_breached?'red':'yellow'}">${fmt(d.budget_used*100,0)}%</b></div><div class="bar"><div style="width:${Math.min(100,d.budget_used*100)}%;background:${d.budget_breached?'#fc8a96':'#edc77b'}"></div></div><small>Historical maximum drawdown ${fmt(lost*100)}% / user budget ${fmt(d.budget*100,0)}%. ${d.budget_breached?'Budget exceeded. This did not trigger an automatic stop.':'A learning threshold, not a guarantee or margin calculation.'}</small></div></section></div>

 ${d.complete?replayDebrief(d):`<div class="grid2 equal"><section class="panel"><div class="panelHead"><h2>Your next decision</h2><span class="pill">EXECUTE NEXT CLOSE</span></div><p class="muted">Keep your current holdings, or set new target weights. One turn reveals up to ten common trading sessions.</p><div class="controls"><label>Allocation shortcut<select id="replayPreset"><option value="custom">Custom targets</option><option value="balanced">Balanced launch · 60% equities</option><option value="lower">Lower equity · 20% equities</option><option value="higher">Equity-heavy · 80% equities</option><option value="cash">All cash</option></select></label></div>${replayWeights('turn',d.last_weights)}<div class="replayActions"><button id="holdReplay" class="btn">Keep holdings · Reveal next chapter</button><button id="rebalanceReplay" class="primary">Rebalance · Reveal next chapter →</button></div><small>Targets are user choices, not recommendations. Keep holdings does not rebalance. Cash has a zero assumed return. Both buys and sells pay 5 bps fees + 5 bps slippage.</small><div id="replayError"></div></section><section class="panel"><h2>What you know at this point</h2><article><h3>SPY trend & realized risk</h3><p>Observed close ${fmt(d.observations.at(-1)?.SPY)}; 60-session average ${fmt(d.spy_sma60)}; 20-return annualized volatility ${pct(d.spy_volatility)}. The fixed rule uses the prior session’s values before execution.</p></article><article><h3>Current holdings</h3><p>${Object.entries(p.weights).map(([s,w])=>`${s} ${fmt(w*100,1)}%`).join(' · ')} · Cash ${fmt(p.cash_weight*100,1)}%</p></article><article><h3>${d.historical_release?'Historical policy release':'Historical news capsule locked'}</h3>${d.historical_release?`<p>${link(d.historical_release.url,d.historical_release.title)}</p><small>Published ${esc(d.historical_release.published_at)}. ${esc(d.historical_release.note)}</small>`:'<p>No selected policy release has been published by the displayed point in this world. Future headlines remain hidden.</p>'}</article></section></div>`}
 <section class="panel" style="margin-top:20px"><div class="panelHead"><h2>Three routes through the revealed world</h2><span class="pill">SAME HISTORY · SAME COST MODEL</span></div>${d.curve.length<2?empty('Your first route segment appears after the next decision. No future returns are drawn.'):chart(d.curve,[{key:'player',label:'Your decisions',color:'#66dfb3'},{key:'hold',label:'Initial allocation, held',color:'#8daffb'},{key:'rule',label:'Fixed risk rule',color:'#edc77b'}])}<small>All start in cash; purchases occur no earlier than the next close. Future wealth paths are not included in this response.</small></section>
 <section class="panel" style="margin-top:20px"><h2>Decision log / no rewinding this route</h2><div class="scroll"><table><thead><tr><th>Round</th><th>Information through</th><th>Next-close execution</th><th>Decision</th><th>Revealed through</th></tr></thead><tbody>${d.decisions.length?d.decisions.map(x=>`<tr><td>${x.turn+1}</td><td>${esc(x.observed_date)}</td><td>${esc(x.execution_date)}</td><td>${x.action==='rebalance'?'New targets':'Keep holdings / initial launch'}</td><td>${esc(x.revealed_through)}</td></tr>`).join(''):'<tr><td colspan="5">Launch prepared. The first purchase will execute at the next session close.</td></tr>'}</tbody></table></div><details><summary>Models, costs and source evidence</summary><ul>${d.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><pre>${esc(JSON.stringify(d.sources,null,2))}</pre></details></section>`;
 $('#restartReplay').onclick=()=>{state.replay=null;renderReplaySetup();};$('#exportReplay').onclick=()=>downloadJSON(d,`alphascope-storm-${d.scenario_key}-round-${d.turn}.json`);
 if(!d.complete){wireReplayWeights('turn',valid=>$('#rebalanceReplay').disabled=!valid);$('#replayPreset').onchange=()=>{const presets={balanced:{SPY:60,GLD:15,USO:10,TLT:10},lower:{SPY:20,GLD:20,USO:0,TLT:20},higher:{SPY:80,GLD:10,USO:10,TLT:0},cash:{SPY:0,GLD:0,USO:0,TLT:0}};const w=presets[$('#replayPreset').value];if(w){for(const s of Object.keys(w))$('#turn'+s).value=w[s];$('#turnSPY').dispatchEvent(new Event('input'));}};$('#holdReplay').onclick=()=>takeReplayTurn('hold');$('#rebalanceReplay').onclick=()=>takeReplayTurn('rebalance');}
}
function replayDebrief(d){const keys=['player','hold','rule'],labels={player:'Your decisions',hold:'Initial allocation, held',rule:'Fixed risk rule'};const p=d.paths.player;return `<section class="panel replayDebrief" style="margin-top:20px"><div class="eyebrow">THE MULTIVERSE DEBRIEF</div><h2>There was more than one way through.</h2><p class="muted">Your result reflects this route through known history. It does not prove skill, causality or future profitability.</p><div class="scroll"><table><thead><tr><th>Route</th><th>Final wealth</th><th>Total return</th><th>Max drawdown</th><th>Costs</th><th>Execution fills</th></tr></thead><tbody>${keys.map(k=>{const x=d.paths[k];return `<tr><td>${labels[k]}</td><td>$${fmt(x.nav,0)}</td><td class="${cls(x.metrics.total_return)}">${pct(x.metrics.total_return)}</td><td class="red">${pct(x.metrics.max_drawdown)}</td><td>$${fmt(x.cost_usd)}</td><td>${x.execution_fill_count}</td></tr>`;}).join('')}</tbody></table></div><div class="evidence"><div><h3>The opportunity cost</h3><p>Your final wealth was ${p.nav>=d.paths.hold.nav?'above':'below'} the initial-allocation hold path by $${fmt(Math.abs(p.nav-d.paths.hold.nav),0)}. Lower drawdown can come with missed recovery.</p></div><div><h3>The risk trade-off</h3><p>Your ${fmt(d.budget*100,0)}% drawdown budget was ${d.budget_breached?'exceeded':'not exceeded'} in this realized path. That is an observation, not a future safety guarantee.</p></div><div><h3>What would change your mind?</h3><p>Repeat in the other historical world and inspect costs. Familiarity with this outcome limits the value of replaying it as an independent test.</p></div></div></section>`;}
async function takeReplayTurn(action){const current=state.replay;const payload={id:current.id,expected_turn:current.turn,action,...(action==='rebalance'?{weights:collectReplayWeights('turn')}:{})};$('#holdReplay').disabled=true;$('#rebalanceReplay').disabled=true;$('#holdReplay').textContent='Revealing observed history…';try{const next=await replayPost('/api/replay/advance',payload);if(state.replay?.id===current.id){state.replay=next;if(state.view==='replay')renderStormReplay();}}catch(e){if($('#replayError'))$('#replayError').innerHTML=`<div class="error">${esc(e.message)}</div>`;if($('#holdReplay')){$('#holdReplay').disabled=false;$('#holdReplay').textContent='Keep holdings · Reveal next chapter';wireReplayWeights('turn',valid=>$('#rebalanceReplay').disabled=!valid);}}}
